  cycle_nudge_menstruation_iron_body: "Die Blutung verbraucht Eisen, Liebes. Kombiniere eine Mahlzeit mit Spinat oder Linsen mit etwas Zitrusfrüchtigem – Vitamin C verdoppelt ungefähr, wie viel du aufnimmst.",
