  cycle_nudge_follicular_hydrate_body: "Er sollte klarer und dehnbarer werden, je näher das Fenster rückt. Schleim besteht größtenteils aus Wasser – 2 bis 2,5 Liter am Tag halten das Signal gut lesbar.",
