  dataInv_title: "Daten, die wir speichern",
  dataInv_subtitle: "nichts bleibt verborgen",
  dataInv_intro: "Eine aktuelle Übersicht über alles, was grandma.app gerade über dich speichert. Tippe auf Exportieren für die vollständige, maschinenlesbare Kopie.",
  dataInv_sectionHolding: "Was wir speichern",
